"""Export the OpenAPI specification generated by FastAPI to docs/openapi.json."""
import json
import sys
from pathlib import Path

ROOT = Path(__file__).resolve().parent.parent
sys.path.insert(0, str(ROOT))

from m4.api.app import app  # noqa: E402

if __name__ == "__main__":
    out = ROOT / "docs" / "openapi.json"
    out.write_text(json.dumps(app.openapi(), indent=2), encoding="utf-8")
    print(f"OpenAPI written to {out.relative_to(ROOT)} ({len(app.openapi()['paths'])} paths)")
